        // Tailwind CSS — marca oficial.
        'tailwind' => 'M12.001,4.8c-3.2,0-5.2,1.6-6,4.8c1.2-1.6,2.6-2.2,4.2-1.8c0.913,0.228,1.565,0.89,2.288,1.624 C13.666,10.618,15.027,12,18.001,12c3.2,0,5.2-1.6,6-4.8c-1.2,1.6-2.6,2.2-4.2,1.8c-0.913-0.228-1.565-0.89-2.288-1.624 C16.337,6.182,14.976,4.8,12.001,4.8z M6.001,12c-3.2,0-5.2,1.6-6,4.8c1.2-1.6,2.6-2.2,4.2-1.8c0.913,0.228,1.565,0.89,2.288,1.624 c1.177,1.194,2.538,2.576,5.512,2.576c3.2,0,5.2-1.6,6-4.8c-1.2,1.6-2.6,2.2-4.2,1.8c-0.913-0.228-1.565-0.89-2.288-1.624 C10.337,13.382,8.976,12,6.001,12z',
    ];

    // Cor OFICIAL de cada marca. Não entra na paleta do kit: vive só dentro do
    // objeto (cubo em CSS e material 3D), como pintura de um objeto físico. É
    // o que torna oito cubos distinguíveis a 40px de distância.
    $colors = [
        'laravel' => '#ff2d20', // Laravel
        'php' => '#777bb4', // PHP
        'postgres' => '#336791', // PostgreSQL
        'redis' => '#ff4438', // Redis
        'docker' => '#2496ed', // Docker
        'livewire' => '#4e56a6', // Livewire
        'filament' => '#fdae4b', // Filament
        'tailwind' => '#06b6d4', // Tailwind CSS
    ];

    $path = $marks[$name] ?? '';
    $color = $colors[$name] ?? '#777bb4';
    $asCube = $cube ?? false;

    // TINTA DO DECALQUE. Quase toda marca aqui é escura o bastante para o logo
    // branco; o âmbar do Filament não é — branco sobre ele fica em 1,9:1 e o
    // desenho some. As próprias guias de marca pedem a versão escura sobre
    // fundo claro, então a regra é essa, calculada e não escolhida a dedo:
    // luminância relativa acima de 45% → decalque quase-preto.
    $rgb = sscanf($color, '#%02x%02x%02x');
    $channel = static fn (int $value): float => ($v = $value / 255) <= 0.03928 ? $v / 12.92 : (($v + 0.055) / 1.055) ** 2.4;
    $luminance = 0.2126 * $channel($rgb[0]) + 0.7152 * $channel($rgb[1]) + 0.0722 * $channel($rgb[2]);
    $ink = $luminance > 0.45 ? '#1c1917' : '#ffffff';
@endphp

@if ($asCube)
    <span
        class="sky-tech-cube {{ $cubeClass ?? 'h-16 w-16' }}"
        style="--sky-tech: {{ $color }}; --sky-tech-ink: {{ $ink }}; --sky-tech-tilt: {{ $tilt ?? '-8deg' }}"
        data-sky-color="{{ $color }}"
        data-sky-ink="{{ $ink }}"
        data-sky-tech="{{ $name }}"
    >
        @include('landing.tech-mark', ['name' => $name, 'class' => $class ?? 'h-7 w-7', 'cube' => false])
    </span>
@else
    {{-- fill="currentColor": o decalque é branco no cubo e herda a tinta do
         contexto em qualquer outro lugar. Nunca stroke — logo oficial é forma
         preenchida, e engrossar contorno deforma a marca. --}}
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false" data-sky-mark="{{ $name }}" class="{{ $class ?? 'h-6 w-6' }}">
        <path d="{{ $path }}" />
    </svg>
@endif
